def min_operations(nums, x):
    n = len(nums)
    best = -1
    for left_count in range(n + 1):
        for right_count in range(n + 1 - left_count):                 # every combination of left and right removals
            removed_sum = sum(nums[:left_count]) + sum(nums[n - right_count:])
            if removed_sum == x:
                total = left_count + right_count
                if best == -1 or total < best:
                    best = total
    return best


if __name__ == "__main__":
    print(min_operations([1, 1, 4, 2, 3], 5))

