import java.util.*;

public class Main {
    int minOperations(int[] nums, int x) {
        int n = nums.length;
        int best = -1;
        for (int leftCount = 0; leftCount <= n; leftCount++) {
            for (int rightCount = 0; rightCount <= n - leftCount; rightCount++) {  // every combination of left and right
                int removedSum = 0;
                for (int i = 0; i < leftCount; i++) removedSum += nums[i];
                for (int i = n - rightCount; i < n; i++) removedSum += nums[i];
                if (removedSum == x) {
                    int total = leftCount + rightCount;
                    if (best == -1 || total < best) best = total;
                }
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.minOperations(new int[]{1, 1, 4, 2, 3}, 5));
    }
}

