def min_operations(nums, x):
    total = sum(nums)
    target = total - x
    if target < 0:
        return -1
    if target == 0:
        return len(nums)
    left = 0
    current_sum = 0
    best_length = -1
    for right in range(len(nums)):
        current_sum += nums[right]
        while current_sum > target:
            current_sum -= nums[left]                              # shrink until the sum no longer exceeds target
            left += 1
        if current_sum == target:
            best_length = max(best_length, right - left + 1)
    return len(nums) - best_length if best_length != -1 else -1


if __name__ == "__main__":
    print(min_operations([1, 1, 4, 2, 3], 5))

