import java.util.*;

public class Main {
    int minOperations(int[] nums, int x) {
        int total = 0;
        for (int num : nums) total += num;
        int target = total - x;
        if (target < 0) return -1;
        if (target == 0) return nums.length;
        int left = 0, currentSum = 0, bestLength = -1;
        for (int right = 0; right < nums.length; right++) {
            currentSum += nums[right];
            while (currentSum > target) {
                currentSum -= nums[left];                                   // shrink until the sum no longer exceeds target
                left++;
            }
            if (currentSum == target) {
                bestLength = Math.max(bestLength, right - left + 1);
            }
        }
        return bestLength == -1 ? -1 : nums.length - bestLength;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.minOperations(new int[]{1, 1, 4, 2, 3}, 5));
    }
}

